(98, 'Marshall Stanmore III Speaker', 'marshall-stanmore-iii-speaker', 'Marshall Stanmore III Speaker - Sản phẩm chính hãng bảo hành 12 tháng, giao hàng toàn quốc.', 'Chi tiết về Marshall Stanmore III Speaker: Thiết kế hiện đại, cấu hình mạnh mẽ, đáp ứng hoàn hảo nhu cầu làm việc, giải trí và học tập hàng ngày. Đầy đủ phụ kiện và tem bảo hành chính hãng.', 'Marshall', 9490000, 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?q=80&w=600', 5, 5, 'SELLING'),
(99, 'Nintendo Switch OLED Console', 'nintendo-switch-oled-console', 'Nintendo Switch OLED Console - Sản phẩm chính hãng bảo hành 12 tháng, giao hàng toàn quốc.', 'Chi tiết về Nintendo Switch OLED Console: Thiết kế hiện đại, cấu hình mạnh mẽ, đáp ứng hoàn hảo nhu cầu làm việc, giải trí và học tập hàng ngày. Đầy đủ phụ kiện và tem bảo hành chính hãng.', 'Nintendo', 7490000, 'https://images.unsplash.com/photo-1578303512597-81e6cc155b3e?q=80&w=600', 5, 5, 'SELLING'),
(100, 'SanDisk Extreme PRO SSD 2TB', 'sandisk-extreme-pro-ssd-2tb', 'SanDisk Extreme PRO SSD 2TB - Sản phẩm chính hãng bảo hành 12 tháng, giao hàng toàn quốc.', 'Chi tiết về SanDisk Extreme PRO SSD 2TB: Thiết kế hiện đại, cấu hình mạnh mẽ, đáp ứng hoàn hảo nhu cầu làm việc, giải trí và học tập hàng ngày. Đầy đủ phụ kiện và tem bảo hành chính hãng.', 'SanDisk', 4490000, 'https://images.unsplash.com/photo-1629126786844-3453b34208a0?q=80&w=600', 5, 5, 'SELLING');
